package smartcampus;
import java.awt.*;import java.sql.*;
public class Vehicles extends Panel{TextField plate=UI.field(""),owner=UI.field(""),type=UI.field("Car");TextArea out=new TextArea();Vehicles(Frame f){setLayout(new BorderLayout(8,8));setBackground(UI.BG);add(UI.label("VEHICLE MANAGEMENT — CRUD",22,UI.NAVY),BorderLayout.NORTH);Panel p=new Panel(new GridLayout(0,2,5,5));p.add(new Label("Plate Number"));p.add(plate);p.add(new Label("Owner User ID"));p.add(owner);p.add(new Label("Vehicle Type"));p.add(type);Button add=UI.button("ADD VEHICLE",UI.GREEN),del=UI.button("DELETE PLATE",UI.RED),load=UI.button("REFRESH",UI.CYAN);p.add(add);p.add(del);p.add(load);add(p,BorderLayout.WEST);out.setEditable(false);add(out,BorderLayout.CENTER);add.addActionListener(e->add());del.addActionListener(e->del());load.addActionListener(e->load());load();}void add(){try(Connection c=DB.get();PreparedStatement p=c.prepareStatement("insert into vehicles(user_id,plate_number,vehicle_type) values(?,?,?)")){p.setInt(1,Integer.parseInt(owner.getText()));p.setString(2,plate.getText());p.setString(3,type.getText());p.executeUpdate();load();}catch(Exception e){out.setText(e.getMessage());}}void del(){try(Connection c=DB.get();PreparedStatement p=c.prepareStatement("delete from vehicles where plate_number=?")){p.setString(1,plate.getText());p.executeUpdate();load();}catch(Exception e){out.setText(e.getMessage());}}void load(){try(Connection c=DB.get()){ResultSet r=c.createStatement().executeQuery("select vehicle_id,user_id,plate_number,vehicle_type from vehicles order by vehicle_id");StringBuilder s=new StringBuilder("ID | USER ID | PLATE | TYPE\n");while(r.next())s.append(r.getInt(1)).append(" | ").append(r.getInt(2)).append(" | ").append(r.getString(3)).append(" | ").append(r.getString(4)).append('\n');out.setText(s.toString());}catch(Exception e){out.setText("DB error: "+e.getMessage());}}}
